"""PyShield runtime. Generated by the PyShield builder; do not edit.

Module payloads are encrypted with a key derived from the build master key.
The license carries authorization data only; it does not contain the module
key. Before any protected module is loaded the signed package manifest is
checked, so protected files and the runtime itself cannot be modified without
detection. Bytecode caches are never read from the deployment directory and any
cache that is not part of the signed manifest is rejected.
"""

from __future__ import annotations

import contextlib
import hashlib
import hmac
import json
import marshal
import os
import platform
import sys
import tempfile
import threading
import time
import types
import zlib
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from . import _crypto
from . import _ed25519
from . import _keyring
from . import _machine
