BUILD_ID = "ef3bb96a41a169b5"
SIGNING_PUBLIC_KEY_B85 = "FPI0sQHWCQg9q~ysme4L>QGJSX0HgGkkKRmQ(4v0"
PYTHON_VERSION = "3.12"
CIPHER = "chacha"
INTEGRITY_MODE = "off"
LICENSE_FORMAT = 3

LICENSE_SALT = b"pyshield-license-v3"
LICENSE_AAD_PREFIX = b"pyshield-license-v3:"
BUILD_KEY_SALT = b"pyshield-build-key-v1"

MANIFEST_FILE = ".pyshield-manifest.json"
MANIFEST_FORMAT = 1
MANIFEST_CATEGORIES = ("code", "runtime", "data")

RUNTIME_PACKAGE_NAME = "_shield_runtime"
BYTECODE_SUFFIXES = (".pyc", ".pyo")

STATE_FORMAT = 2
STATE_PURPOSE = "pyshield-clock"
STATE_DIR_ENV = "PYSHELD_STATE_DIR"
STATE_ANCHOR_DIR_ENV = "PYSHELD_STATE_ANCHOR_DIR"
VOLATILE_STATE_ENV = "PYSHELD_ALLOW_VOLATILE_STATE"
ALLOW_LEGACY_STATE_ENV = "PYSHELD_ALLOW_LEGACY_STATE"
CLOCK_SKEW_DAYS = 1
STATE_MAX_FUTURE_DAYS = 7
STATE_LOCK_TIMEOUT_SECONDS = 5.0
STATE_TTL_SECONDS = 300

BIND_ANY = "any"
BIND_FIRST_RUN = "first-run"
BIND_FIXED = "fixed"
BINDING_FILE = ".pyshield-binding.json"
BINDING_FILE_ENV = "PYSHELD_BINDING_FILE"
BINDING_ANCHOR_SUFFIX = ".anchor"
BINDING_FORMAT = 1
BINDING_SALT = b"pyshield-binding-v1"
LEGACY_MARKER_PURPOSE = "pyshield-legacy-migration"
LEGACY_MARKER_SUFFIX = ".legacy-migrated"
LEGACY_MARKER_FORMAT = 1

_lock = threading.RLock()
_state: dict | None = None
_state_loaded_at = 0.0
_integrity: dict | None = None
_clock_started = False
_binding_started = False


class LicenseError(RuntimeError):
    """Raised when the build's license or package integrity is invalid."""


def _dist_dir() -> Path:
    return Path(__file__).resolve().parent.parent


def _runtime_dir() -> Path:
    return Path(__file__).resolve().parent


def _license_candidates() -> list[Path]:
    candidates: list[Path] = []
    env = os.environ.get("PYSHELD_LICENSE")
    if env:
        candidates.append(Path(env))
    candidates.append(_dist_dir() / "pyshield.lic")
    candidates.append(_runtime_dir() / "pyshield.lic")
    return candidates


def _read_license() -> tuple[Path, bytes]:
    for path in _license_candidates():
        if path.is_file():
            return path, path.read_bytes()
    locations = ", ".join(str(item) for item in _license_candidates()[:-1])
    raise LicenseError(
        "PyShield license not found; expected pyshield.lic next to manage.py"
        + (f", or PYSHELD_LICENSE ({locations})" if locations else "")
    )


def _master_key() -> bytes:
    return _keyring.master_key()


def _build_key(master_key: bytes) -> bytes:
    return _crypto.hkdf_sha256(
        master_key, salt=BUILD_KEY_SALT, info=BUILD_ID.encode("utf-8"), length=32
    )


def _license_key(master_key: bytes) -> bytes:
    return _crypto.hkdf_sha256(
        master_key, salt=LICENSE_SALT, info=BUILD_ID.encode("utf-8"), length=32
    )


def _check_runtime() -> None:
    if platform.python_implementation() != "CPython":
        raise LicenseError("PyShield builds require CPython")
    if "%d.%d" % sys.version_info[:2] != PYTHON_VERSION:
        raise LicenseError(
            f"this build targets CPython {PYTHON_VERSION}, "
            f"but the running interpreter is {platform.python_version()}"
        )


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _safe_relative(relative: str) -> bool:
    if not relative or "\\" in relative or relative.startswith("/") or ":" in relative:
        return False
    return ".." not in relative.split("/")


def _isolate_bytecode() -> None:
    """Keep the interpreter away from bytecode caches in the deployment tree.

    CPython accepts a timestamp-based ``.pyc`` whenever its header matches the
    source ``mtime``/``size``; the payload itself is not authenticated. In a
    writable deployment that lets an attacker plant ``<pkg>/__pycache__/*.pyc``
    which runs instead of the protected stub while every signed file still
    hashes correctly. Pointing ``sys.pycache_prefix`` at an unpredictable path
    and disabling cache writes keeps later imports from reading those files.
    """
    if getattr(sys, "_pyshield_bytecode_isolated", False):
        return
    try:
        sys.pycache_prefix = str(
            Path(tempfile.gettempdir())
            / f"pyshield-bytecode-{BUILD_ID[:16]}-{os.urandom(8).hex()}"
        )
    except Exception:
        pass
    sys.dont_write_bytecode = True
    sys._pyshield_bytecode_isolated = True


# Protected packages are imported after this module, so installing the
# isolation here means their import lookups never see a planted cache entry.
_isolate_bytecode()


def _imported_bytecode_paths() -> set[str]:
    """Cache files CPython itself loaded for modules imported so far.

    When the entry point is a package (``python -c "import mypkg"``), CPython
    writes ``mypkg/__pycache__`` before the stub body imports this runtime, so
    that cache is legitimate even though the manifest cannot cover it. Only
    caches for modules that are already imported are skipped; a cache planted
    for a module that has not been imported yet is still rejected.
    """
    paths: set[str] = set()
    for module in list(sys.modules.values()):
        cached = getattr(module, "__cached__", None)
        if not isinstance(cached, str) or not cached:
            continue
        try:
            # resolve() expands 8.3 short names (CI runners export TEMP as
            # C://Users//RUNNER~1//...), which plain abspath keeps.
            paths.add(os.path.normcase(str(Path(cached).resolve())))
        except (OSError, ValueError):
            continue
    return paths


def _prune_imported_caches(root: Path) -> None:
    """Remove the cache CPython wrote for an already-imported module.

    ``python -c "import mypkg"`` makes CPython compile and cache
    ``mypkg/__init__.py`` before the stub body imports this runtime. That file
    is legitimate for this process, but leaving it in the deployment would make
    the next start reject the tree. Delete only caches of modules that are
    already in ``sys.modules``; a cache planted for a module that has not been
    imported stays on disk and is reported by the integrity scan.
    """
    imported = _imported_bytecode_paths()
    if not imported:
        return
    runtime_prefix = RUNTIME_PACKAGE_NAME + "/"
    for path in root.rglob("*"):
        if path.suffix.lower() not in BYTECODE_SUFFIXES:
            continue
        try:
            relative = path.relative_to(root).as_posix()
            current = os.path.normcase(str(Path(path).resolve()))
        except (OSError, ValueError):
            continue
        if relative.startswith(runtime_prefix) or current not in imported:
            continue
        try:
            path.unlink()
        except OSError:
            continue


# A package entry point makes CPython cache the stub before this module runs;
# remove that legitimate-but-unlisted cache so the next start still passes.
_prune_imported_caches(_dist_dir())


def _scan_bytecode_caches(root: Path) -> list[str]:
    """Report import caches that no signed manifest entry can cover."""
    failures: list[str] = []
    imported = _imported_bytecode_paths()
    runtime_prefix = RUNTIME_PACKAGE_NAME + "/"
    for path in sorted(root.rglob("*")):
        try:
            if path.is_symlink():
                continue
            relative = path.relative_to(root).as_posix()
        except (OSError, ValueError):
            continue
        if relative.startswith(runtime_prefix):
            # A forged runtime cache is equivalent to replacing the runtime,
            # which the documentation already lists as an offline boundary.
            continue
        try:
            is_file = path.is_file()
        except OSError:
            continue
        if is_file and path.suffix.lower() in BYTECODE_SUFFIXES:
            try:
                current = os.path.normcase(str(Path(path).resolve()))
            except (OSError, ValueError):
                current = ""
            if current in imported:
                continue
            failures.append(f"{relative}: unsigned bytecode cache")
        if len(failures) >= 20:
            failures.append("more bytecode caches were not listed")
            break
    return failures


def _load_manifest() -> dict:
    path = _dist_dir() / MANIFEST_FILE
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        raise LicenseError(
            f"PyShield package manifest {MANIFEST_FILE} is missing; deploy the complete build"
        ) from exc
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise LicenseError(f"PyShield package manifest {MANIFEST_FILE} is damaged") from exc
    if not isinstance(payload, dict) or payload.get("format") != MANIFEST_FORMAT:
        raise LicenseError("PyShield package manifest has an unsupported format")
    if payload.get("build_id") != BUILD_ID:
        raise LicenseError("PyShield package manifest belongs to a different build")
    if payload.get("cipher") != CIPHER:
        raise LicenseError("PyShield package manifest cipher does not match this build")
    if payload.get("integrity") != INTEGRITY_MODE:
        raise LicenseError("PyShield package manifest integrity mode does not match this build")
    signature = payload.get("signature")
    try:
        signed = (
            isinstance(signature, str)
            and _ed25519.verify(
                _crypto.b85decode(SIGNING_PUBLIC_KEY_B85),
                _crypto.manifest_signing_message(payload),
                _crypto.b85decode(signature),
            )
        )
    except Exception:
        signed = False
    if not signed:
        raise LicenseError("PyShield package manifest signature is invalid")
    files = payload.get("files")
    if not isinstance(files, dict) or not files:
        raise LicenseError("PyShield package manifest contains no file list")
    return payload


def _scan_integrity(full: bool) -> dict:
    """Hash protected package files; returns {enabled, checked, failures}."""
    if INTEGRITY_MODE == "off":
        return {"enabled": False, "checked": 0, "failures": []}

    payload = _load_manifest()
    categories = {"code", "runtime"}
    if full or INTEGRITY_MODE == "full":
        categories.add("data")

    root = _dist_dir()
    failures: list[str] = []
    checked = 0
    for relative, info in payload["files"].items():
        if not _safe_relative(relative) or not isinstance(info, dict):
            failures.append(f"invalid manifest entry: {relative!r}")
            continue
        category = info.get("category")
        if category not in MANIFEST_CATEGORIES:
            failures.append(f"unknown category for {relative}")
            continue
        if category not in categories:
            continue
        target = root / relative
        try:
            if target.is_symlink() or not target.is_file():
                raise OSError("file is missing")
            if target.stat().st_size != info.get("size"):
                raise OSError("size mismatch")
            if _sha256_file(target) != info.get("sha256"):
                raise OSError("hash mismatch")
        except OSError as exc:
            failures.append(f"{relative}: {exc}")
        checked += 1
    failures.extend(_scan_bytecode_caches(root))
    return {"enabled": True, "checked": checked, "failures": failures}


def _enforce_integrity() -> None:
    global _integrity
    if _integrity is None:
        with _lock:
            if _integrity is None:
                _integrity = _scan_integrity(full=INTEGRITY_MODE == "full")
    failures = _integrity["failures"]
    if failures:
        details = "; ".join(failures[:5])
        if len(failures) > 5:
            details += f"; and {len(failures) - 5} more"
        raise LicenseError(
            "PyShield package integrity check failed (" + details + "); "
            "restore the original files or contact the vendor"
        )


def verify_package(full: bool = False) -> dict:
    """Verify the signed package manifest without loading a license.

    By default protected code and the runtime are hashed; ``full=True`` also
    hashes templates, static files and other packaged data.
    """
    try:
        report = _scan_integrity(full=full)
    except LicenseError as exc:
        return {"ok": False, "enabled": INTEGRITY_MODE != "off", "checked": 0, "failures": [str(exc)]}
    return {
        "ok": not report["failures"],
        "enabled": report["enabled"],
        "checked": report["checked"],
        "failures": report["failures"],
    }


def _state_dir() -> Path:
    directory = os.environ.get(STATE_DIR_ENV)
    if directory:
        return Path(directory)
    try:
        home = Path.home()
    except (RuntimeError, OSError):
        return _runtime_dir()
    return home / ".pyshield"


def _state_anchor_dir() -> Path | None:
    directory = os.environ.get(STATE_ANCHOR_DIR_ENV)
    if directory:
        return Path(directory)
    if os.environ.get(STATE_DIR_ENV):
        # Explicit state directories keep the anchor beside the primary file.
        return None
    if os.name == "nt":
        base = os.environ.get("LOCALAPPDATA")
        if base:
            return Path(base) / "PyShield" / "state"
    else:
        base = os.environ.get("XDG_STATE_HOME")
        if base:
            return Path(base) / "pyshield"
        try:
            home = Path.home()
        except (RuntimeError, OSError):
            return None
        return home / ".local" / "state" / "pyshield"
    return None


def _clock_paths() -> tuple[Path, Path]:
    name = BUILD_ID + ".state"
    primary = _state_dir() / name
    anchor_dir = _state_anchor_dir()
    if anchor_dir is None:
        return primary, primary.with_name(primary.name + ".anchor")
    return primary, anchor_dir / name


def _allow_volatile_state() -> bool:
    value = os.environ.get(VOLATILE_STATE_ENV, "").strip().lower()
    return value in {"1", "true", "yes", "on"}


def _allow_legacy_state() -> bool:
    value = os.environ.get(ALLOW_LEGACY_STATE_ENV, "").strip().lower()
    return value in {"1", "true", "yes", "on"}


def _legacy_marker_paths(paths: tuple[Path, Path]) -> tuple[Path, ...]:
    markers: list[Path] = []
    for path in paths:
        marker = path.with_name(path.name + LEGACY_MARKER_SUFFIX)
        if marker not in markers:
            markers.append(marker)
    return tuple(markers)


def _legacy_migration_done(paths: tuple[Path, Path]) -> bool:
    """Return True once the one-time legacy migration has been consumed.

    The marker's presence is authoritative. A corrupt, foreign or unreadable
    marker is treated as consumed so it cannot reopen the public-MAC downgrade
    path; a marker created by an attacker only disables legacy migration, which
    fails closed.
    """
    for marker in _legacy_marker_paths(paths):
        try:
            if _secure_store.read_private(marker) is not None:
                return True
        except _secure_store.SecureStoreError:
            return True
    return False


def _write_legacy_migration_marker(
    paths: tuple[Path, Path], machine: str, secret: bytes
) -> None:
    record = {
        "format": LEGACY_MARKER_FORMAT,
        "build_id": BUILD_ID,
        "migrated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }
    try:
        data = _secure_store.seal_state(
            record, machine, LEGACY_MARKER_PURPOSE, secret,
        )
    except (OSError, ValueError) as exc:
        raise LicenseError(
            f"PyShield cannot protect the one-time legacy migration marker: {exc}"
        ) from exc
    failures: list[tuple[Path, OSError]] = []
    written = 0
    for marker in _legacy_marker_paths(paths):
        try:
            _secure_store.write_private(marker, data)
            written += 1
        except OSError as exc:
            failures.append((marker, exc))
    if written == 0:
        marker, exc = failures[0]
        raise LicenseError(
            "PyShield cannot record the one-time legacy migration marker "
            f"in {marker} ({exc}); remove {ALLOW_LEGACY_STATE_ENV} and restore "
            "a keyed state file"
        ) from exc


def _legacy_state_policy(
    paths: tuple[Path, Path],
) -> tuple[bool, str, bool]:
    """Return (allow_legacy, block_reason, marker_seen)."""
    if not _allow_legacy_state():
        return False, "disabled", False
    done = _legacy_migration_done(paths)
    if _clock_started:
        return False, "running", done
    if done:
        return False, "consumed", True
    return True, "", False


@contextlib.contextmanager
def _state_lock(paths: tuple[Path, Path], label: str = "clock state"):
    """Serialize a state read-modify-write across processes when possible.

    The lock file is advisory. If the state directory is not writable, startup
    continues unlocked; reads still retry transient sharing errors and the
    subsequent state write fails closed unless volatile state was explicitly
    allowed.
    """
    lock_path = paths[0].with_name(paths[0].name + ".lock")
    handle = None
    try:
        try:
            lock_path.parent.mkdir(parents=True, exist_ok=True)
            handle = open(lock_path, "a+b")
        except OSError:
            yield
            return
        if os.name == "nt":
            import msvcrt

            handle.seek(0, os.SEEK_END)
            if handle.tell() == 0:
                handle.write(b"\0")
                handle.flush()
                os.fsync(handle.fileno())
            deadline = time.monotonic() + STATE_LOCK_TIMEOUT_SECONDS
            while True:
                try:
                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    break
                except OSError as exc:
                    if time.monotonic() >= deadline:
                        raise LicenseError(
                            f"PyShield could not lock {label}; "
                            "another process is holding the lock"
                        ) from exc
                    time.sleep(0.02)
            try:
                yield
            finally:
                try:
                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
                except OSError:
                    pass
        else:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
            try:
                yield
            finally:
                try:
                    fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
                except OSError:
                    pass
    finally:
        if handle is not None:
            try:
                handle.close()
            except OSError:
                pass


def _clock_machine() -> str:
    return _machine.machine_fingerprint().lower()


def _read_clock_file(
    path: Path,
    machine: str,
    secret: bytes,
    allow_legacy: bool,
    legacy_block: str,
) -> tuple[date | None, bool]:
    try:
        data = _secure_store.read_private(path)
    except _secure_store.SecureStoreError as exc:
        raise LicenseError(
            f"PyShield clock state {path} cannot be read; "
            "restore the file or contact the vendor"
        ) from exc
    if data is None:
        return None, False
    legacy = False
    try:
        record = _secure_store.open_state(data, machine, STATE_PURPOSE, secret)
    except _secure_store.SecureStoreError:
        # Legacy public-MAC state is a downgrade path: anyone who can write the
        # state directory can forge a last_seen value and have it re-sealed
        # with the keyed MAC. Migration is opt-in and one-time only.
        if not allow_legacy:
            if legacy_block == "running":
                reason = (
                    "legacy public-MAC state was introduced while the program "
                    "was running; restore the keyed state file or contact the vendor"
                )
            elif legacy_block == "consumed":
                reason = (
                    "the one-time legacy migration was already consumed; "
                    "restore the keyed state file or contact the vendor"
                )
            else:
                reason = (
                    "rebuild the state or set "
                    f"{ALLOW_LEGACY_STATE_ENV}=1 only for a one-time migration "
                    "from an older build"
                )
            raise LicenseError(
                f"PyShield clock state {path} is damaged or belongs to another "
                f"machine; {reason}"
            )
        try:
            record = _secure_store.open_state(data, machine, STATE_PURPOSE)
            legacy = True
        except _secure_store.SecureStoreError as exc:
            raise LicenseError(
                f"PyShield clock state {path} is damaged or belongs to another machine; "
                "restore the file or contact the vendor"
            ) from exc
    if (
        not isinstance(record, dict)
        or record.get("format") != STATE_FORMAT
        or record.get("build_id") != BUILD_ID
    ):
        raise LicenseError(
            f"PyShield clock state {path} is invalid; restore the file or contact the vendor"
        )
    try:
        seen = date.fromisoformat(str(record["last_seen"]))
    except (KeyError, TypeError, ValueError) as exc:
        raise LicenseError(
            f"PyShield clock state {path} is damaged; restore the file or correct the system clock"
        ) from exc
    if legacy and seen > date.today():
        raise LicenseError(
            f"PyShield legacy clock state {path} contains a future date "
            f"({seen.isoformat()}); restore a keyed state file or correct the "
            "system clock"
        )
    if seen > date.today() + timedelta(days=STATE_MAX_FUTURE_DAYS):
        raise LicenseError(
            f"PyShield clock state {path} contains an implausible future date "
            f"({seen.isoformat()}); correct the system clock or reset the state"
        )
    return seen, legacy


def _write_clock(seen: date, paths: tuple[Path, Path], secret: bytes) -> None:
    record = {
        "format": STATE_FORMAT,
        "build_id": BUILD_ID,
        "last_seen": seen.isoformat(),
    }
    try:
        data = _secure_store.seal_state(
            record, _clock_machine(), STATE_PURPOSE, secret,
        )
    except (OSError, ValueError) as exc:
        raise LicenseError(f"PyShield cannot protect clock state: {exc}") from exc
    failures: list[tuple[Path, OSError]] = []
    written = 0
    for path in paths:
        try:
            _secure_store.write_private(path, data)
            written += 1
        except OSError as exc:
            failures.append((path, exc))
    if written == 0:
        if _allow_volatile_state():
            # Explicit opt-out for read-only deployments. Rollback
            # detection is then volatile and must be documented.
            return
        path, exc = failures[0]
        raise LicenseError(
            f"PyShield cannot record clock state in {path} ({exc}); "
            f"make the directory writable or set {VOLATILE_STATE_ENV}=1 "
            "for a read-only deployment"
        ) from exc
    # If one copy failed, keep running with the copy that was written. The next
    # read aligns both records to the newer date instead of bricking the app.


def _read_clock_locked(
    secret: bytes, paths: tuple[Path, Path], machine: str
) -> tuple[date | None, tuple[Path, Path]]:
    global _clock_started
    allow_legacy, legacy_block, legacy_done = _legacy_state_policy(paths)
    primary_seen, primary_legacy = _read_clock_file(
        paths[0], machine, secret, allow_legacy, legacy_block,
    )
    anchor_seen, anchor_legacy = _read_clock_file(
        paths[1], machine, secret, allow_legacy, legacy_block,
    )
    migrated = primary_legacy or anchor_legacy

    def consume_legacy_opt_in() -> None:
        # A successful keyed read while the explicit opt-in is set also
        # consumes the opt-in. This prevents a permanently exported
        # PYSHELD_ALLOW_LEGACY_STATE=1 from reopening the public-MAC path
        # after the keyed state has already been established.
        if migrated or (
            _allow_legacy_state() and not legacy_done and not _clock_started
        ):
            _write_legacy_migration_marker(paths, machine, secret)

    if primary_seen is not None and anchor_seen is not None and primary_seen != anchor_seen:
        # A transient failure between the two writes must not brick the
        # installation. Taking the newer date preserves rollback detection and
        # rewrites both copies to the same value.
        seen = max(primary_seen, anchor_seen)
        _write_clock(seen, paths, secret)
        consume_legacy_opt_in()
        return seen, paths
    seen = primary_seen if primary_seen is not None else anchor_seen
    if seen is None:
        if _clock_started:
            raise LicenseError(
                "PyShield clock state disappeared while the program was running; "
                "restore it from backup or contact the vendor"
            )
        return None, paths
    if (
        primary_seen is None
        or anchor_seen is None
        or primary_legacy
        or anchor_legacy
    ):
        # Restore a deleted copy or migrate the public-MAC state once.
        _write_clock(seen, paths, secret)
        consume_legacy_opt_in()
    elif _allow_legacy_state() and not legacy_done and not _clock_started:
        consume_legacy_opt_in()
    return seen, paths


def _read_clock(secret: bytes) -> tuple[date | None, tuple[Path, Path]]:
    paths = _clock_paths()
    with _state_lock(paths):
        return _read_clock_locked(secret, paths, _clock_machine())


def _binding_paths() -> tuple[Path, Path]:
    override = os.environ.get(BINDING_FILE_ENV)
    if override:
        primary = Path(override)
        return primary, Path(str(primary) + BINDING_ANCHOR_SUFFIX)
    primary = _dist_dir() / BINDING_FILE
    anchor = _runtime_dir() / (BINDING_FILE + BINDING_ANCHOR_SUFFIX)
    return primary, anchor


def _binding_key(build_key: bytes) -> bytes:
    return _crypto.hkdf_sha256(
        build_key, salt=BINDING_SALT, info=BUILD_ID.encode("utf-8"), length=32
    )


def _binding_mac(key: bytes, fingerprint: str, bound_at: str) -> str:
    message = "|".join((BUILD_ID, fingerprint, bound_at)).encode("utf-8")
    return hmac.new(key, message, hashlib.sha256).hexdigest()


def _write_binding_record(
    key: bytes, path: Path, fingerprint: str, bound_at: str
) -> None:
    record = {
        "format": BINDING_FORMAT,
        "build_id": BUILD_ID,
        "fingerprint": fingerprint,
        "bound_at": bound_at,
        "mac": _binding_mac(key, fingerprint, bound_at),
    }
    data = (
        json.dumps(record, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    try:
        # Reuse the same unique-temp-file + sharing-violation retry path as the
        # clock state. A deterministic ``.tmp`` name races when many workers
        # start for the first time at once.
        _secure_store.write_private(path, data)
    except OSError as exc:
        raise LicenseError(
            f"PyShield cannot record the first-run binding in {path} ({exc}); "
            "run once with write permission or ask the vendor for a fixed license"
        ) from exc


def _write_binding_records(
    key: bytes, paths: tuple[Path, ...], fingerprint: str, bound_at: str
) -> None:
    """Write binding copies, tolerating one transient failure.

    A single surviving record is enough to keep the binding authoritative; the
    next startup restores the missing copy. Only a total write failure is
    fatal, matching the clock state's dual-copy behavior.
    """
    failures: list[LicenseError] = []
    written = 0
    for path in paths:
        try:
            _write_binding_record(key, path, fingerprint, bound_at)
            written += 1
        except LicenseError as exc:
            failures.append(exc)
    if written == 0 and failures:
        raise failures[0]


def _read_binding_record(
    key: bytes, path: Path, current: str
) -> dict | None:
    try:
        raw = _secure_store.read_private(path)
    except _secure_store.SecureStoreError as exc:
        raise LicenseError(
            f"PyShield binding file {path} cannot be read: {exc}"
        ) from exc
    if raw is None:
        return None
    try:
        record = json.loads(raw.decode("utf-8"))
        fingerprint = str(record["fingerprint"]).lower()
        bound_at = str(record["bound_at"])
        mac = str(record["mac"])
    except (ValueError, KeyError, TypeError, UnicodeDecodeError) as exc:
        raise LicenseError(
            f"PyShield binding file {path} is damaged; restore it from backup "
            "or contact the vendor"
        ) from exc
    if record.get("format") != BINDING_FORMAT or record.get("build_id") != BUILD_ID:
        raise LicenseError(f"PyShield binding file {path} belongs to a different build")
    if not hmac.compare_digest(_binding_mac(key, fingerprint, bound_at), mac):
        raise LicenseError(
            f"PyShield binding file {path} was modified; restore it from backup "
            "or contact the vendor"
        )
    if fingerprint != current:
        raise LicenseError(
            f"this deployment is bound to machine {fingerprint} "
            f"(current machine {current}); contact the vendor to rebind it"
        )
    return record


def _is_onedir_meipass(path: Path) -> bool:
    """Return True when ``_MEIPASS`` looks like a PyInstaller onedir layout."""
    try:
        executable = Path(sys.executable).resolve()
        return path in {executable.parent, executable.parent / "_internal"}
    except (OSError, RuntimeError):
        return False


def _binding_path_looks_volatile(path: Path) -> bool:
    try:
        resolved = path.resolve()
    except OSError:
        return True
    return any(part.lower().startswith("_mei") for part in resolved.parts)


def _binding_paths_are_volatile() -> bool:
    base = getattr(sys, "_MEIPASS", None)
    if base:
        try:
            extraction = Path(base).resolve()
        except OSError:
            return True
        # Onefile and custom extraction directories are temporary by
        # definition. An explicit binding path must not silently disable this
        # check.
        if not _is_onedir_meipass(extraction):
            return True
    override = os.environ.get(BINDING_FILE_ENV)
    if override:
        primary, anchor = _binding_paths()
        return _binding_path_looks_volatile(primary) or _binding_path_looks_volatile(anchor)
    return False


def _check_first_run_binding(build_key: bytes) -> str:
    global _binding_started
    if _binding_paths_are_volatile():
        raise LicenseError(
            "first-run binding is not supported inside a PyInstaller onefile bundle; "
            "use a fixed fingerprint or build the application as onedir. "
            f"{BINDING_FILE_ENV} cannot make an extraction directory persistent."
        )
    primary_path, anchor_path = _binding_paths()
    key = _binding_key(build_key)
    current = _machine.machine_fingerprint().lower()
    # The whole read-modify-write must be serialized: otherwise two workers can
    # both see "no records", choose different bound_at values, and leave the
    # primary and anchor disagreeing.
    with _state_lock((primary_path, anchor_path), "binding state"):
        primary = _read_binding_record(key, primary_path, current)
        anchor = _read_binding_record(key, anchor_path, current)

        if primary is None and anchor is None:
            if _binding_started:
                raise LicenseError(
                    "PyShield binding records disappeared while the program was running; "
                    "restore them from backup or contact the vendor"
                )
            bound_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
            _write_binding_records(
                key, (primary_path, anchor_path), current, bound_at,
            )
            _binding_started = True
            return current

        if primary is None:
            # Deleting the visible binding file must not turn this into a first run.
            _write_binding_records(
                key, (primary_path,), current, str(anchor["bound_at"]),
            )
            primary = anchor
        elif anchor is None:
            _write_binding_records(
                key, (anchor_path,), current, str(primary["bound_at"]),
            )
            anchor = primary

        if str(primary["bound_at"]) != str(anchor["bound_at"]):
            raise LicenseError(
                "PyShield binding records disagree; restore them from backup or contact the vendor"
            )
        _binding_started = True
        return current


def _check_binding(build_key: bytes, payload: dict) -> tuple[str, list[str], str | None]:
    mode = str(payload.get("bind_mode") or "").strip().lower()
    fingerprints = [str(item).lower() for item in payload.get("fingerprints") or []]
    if mode not in (BIND_ANY, BIND_FIRST_RUN, BIND_FIXED):
        mode = BIND_FIXED if fingerprints else BIND_ANY
    if mode == BIND_ANY:
        return mode, [], None
    if mode == BIND_FIRST_RUN:
        return mode, [], _check_first_run_binding(build_key)
    if not fingerprints:
        raise LicenseError("license uses fixed binding but lists no fingerprints")
    current = _machine.machine_fingerprint().lower()
    if current not in fingerprints:
        raise LicenseError(
            f"this machine is not licensed (fingerprint {current}); "
            "contact the vendor to reissue the license"
        )
    return mode, fingerprints, current


def _check_clock(secret: bytes) -> str:
    global _clock_started
    today = date.today()
    paths = _clock_paths()
    with _state_lock(paths):
        seen, paths = _read_clock_locked(secret, paths, _clock_machine())
        if seen is not None:
            if today < seen - timedelta(days=CLOCK_SKEW_DAYS):
                raise LicenseError(
                    "PyShield detected a system clock rollback "
                    f"(last seen {seen.isoformat()}, today {today.isoformat()}); "
                    "synchronize the system clock and retry"
                )
            if today <= seen:
                _clock_started = True
                return seen.isoformat()
        _write_clock(today, paths, secret)
        _clock_started = True
        return today.isoformat()


def _load_state() -> dict:
    global _state, _state_loaded_at
    if _state is not None:
        return _state
    with _lock:
        if _state is not None:
            return _state

        _check_runtime()
        _enforce_integrity()

        path, sealed = _read_license()
        master_key = _master_key()
        try:
            data = _crypto.open_envelope(
                _license_key(master_key), sealed,
                LICENSE_AAD_PREFIX + BUILD_ID.encode("utf-8"),
            )
            payload = json.loads(data.decode("utf-8"))
        except _crypto.CryptoError as exc:
            raise LicenseError(f"license {path} is invalid or corrupted") from exc
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise LicenseError(f"license {path} is damaged") from exc

        if payload.get("format") != LICENSE_FORMAT:
            raise LicenseError(f"license {path} has an unsupported format")

        signature = payload.get("signature")
        try:
            signed = (
                isinstance(signature, str)
                and _ed25519.verify(
                    _crypto.b85decode(SIGNING_PUBLIC_KEY_B85),
                    _crypto.license_signing_message(payload),
                    _crypto.b85decode(signature),
                )
            )
        except Exception:
            signed = False
        if not signed:
            raise LicenseError(f"license {path} has an invalid signature")

        if payload.get("build_id") != BUILD_ID:
            raise LicenseError(f"license {path} does not belong to this build")

        # Format 3 licenses deliberately do not carry the module key. It is
        # derived locally from the build master key instead.
        build_key = _build_key(master_key)

        bind_mode, fingerprints, bound_fingerprint = _check_binding(build_key, payload)
        last_seen = _check_clock(build_key)

        today = date.today()
        not_before = payload.get("not_before")
        if not_before:
            try:
                issued = date.fromisoformat(str(not_before))
            except ValueError as exc:
                raise LicenseError("license contains an invalid issue date") from exc
            if today < issued - timedelta(days=CLOCK_SKEW_DAYS):
                raise LicenseError(
                    f"license is not valid before {not_before}; synchronize the system clock"
                )

        try:
            grace_days = int(payload.get("grace_days") or 0)
        except (TypeError, ValueError) as exc:
            raise LicenseError("license contains invalid grace days") from exc
        if grace_days < 0:
            raise LicenseError("license contains invalid grace days")

        expires = payload.get("expires")
        in_grace = False
        if expires:
            try:
                expires_date = date.fromisoformat(str(expires))
            except ValueError as exc:
                raise LicenseError("license contains an invalid expiry date") from exc
            if today > expires_date + timedelta(days=grace_days):
                if grace_days:
                    raise LicenseError(
                        f"license expired on {expires} and the {grace_days}-day grace period has ended"
                    )
                raise LicenseError(f"license expired on {expires}")
            in_grace = today > expires_date

        _state = {
            "build_key": build_key,
            "license": path,
            "license_format": LICENSE_FORMAT,
            "not_before": not_before,
            "expires": expires,
            "grace_days": grace_days,
            "in_grace": in_grace,
            "last_seen": last_seen,
            "bind_mode": bind_mode,
            "fingerprints": fingerprints,
            "bound_fingerprint": bound_fingerprint,
            "customer": payload.get("customer"),
        }
        _state_loaded_at = time.monotonic()
        return _state


def _replace_filename(code: types.CodeType, filename: str) -> types.CodeType:
    consts = tuple(
        _replace_filename(item, filename) if isinstance(item, types.CodeType) else item
        for item in code.co_consts
    )
    # Code objects compare equal even when co_filename differs, so always rebuild.
    return code.replace(co_filename=filename, co_consts=consts)


def _state_for_load() -> dict:
    """Refresh the license periodically so expiry checks are not process-lifetime."""
    global _state
    if (
        _state is not None
        and time.monotonic() - _state_loaded_at > STATE_TTL_SECONDS
    ):
        with _lock:
            if (
                _state is not None
                and time.monotonic() - _state_loaded_at > STATE_TTL_SECONDS
            ):
                _state = None
    return _load_state()


def _wipe(buffer: bytearray) -> None:
    if buffer:
        buffer[:] = b"\x00" * len(buffer)


def load_module(name: str, file: str, payload: str, module_id: str) -> None:
    """Decrypt and execute one protected module inside its real module namespace."""
    state = _state_for_load()
    key = _crypto.derive_module_key(state["build_key"], module_id)
    payload_bytes = bytearray()
    compressed = bytearray()
    data: bytearray | None = None
    try:
        payload_bytes.extend(_crypto.b85decode(payload))
        compressed.extend(_crypto.open_envelope(
            key, bytes(payload_bytes), _crypto.module_aad(BUILD_ID, module_id)
        ))
        data = bytearray(zlib.decompress(compressed))
        code = marshal.loads(data)
    except _crypto.CryptoError as exc:
        raise ImportError(f"PyShield: cannot decrypt protected module {module_id}") from exc
    except Exception as exc:
        raise ImportError(f"PyShield: protected module {module_id} is corrupted") from exc
    finally:
        # Best effort: shrink the window in which decrypted bytes sit in the
        # process heap. The code object itself still exists in memory.
        _wipe(payload_bytes)
        _wipe(compressed)
        if data is not None:
            _wipe(data)

    if not isinstance(code, types.CodeType):
        raise ImportError(f"PyShield: protected module {module_id} has an invalid payload")

    code = _replace_filename(code, file)
    module = sys.modules.get(name)
    namespace = module.__dict__ if module is not None else {"__name__": name, "__file__": file}
    exec(code, namespace)


def reload_license() -> dict:
    """Re-read the license file so a renewed license takes effect without a restart."""
    global _state, _state_loaded_at
    with _lock:
        _state = None
        _state_loaded_at = 0.0
    return license_status()


def license_status(refresh: bool = False) -> dict:
    """Return license and clock details; raises LicenseError when unusable."""
    if refresh:
        return reload_license()
    state = _load_state()
    return {
        "build_id": BUILD_ID,
        "license": str(state["license"]),
        "license_format": state["license_format"],
        "not_before": state["not_before"],
        "expires": state["expires"],
        "grace_days": state["grace_days"],
        "in_grace": state["in_grace"],
        "last_seen": state["last_seen"],
        "bind_mode": state["bind_mode"],
        "fingerprints": state["fingerprints"],
        "bound_fingerprint": state["bound_fingerprint"],
        "customer": state["customer"],
        "cipher": CIPHER,
        "integrity": INTEGRITY_MODE,
        "signature": "ed25519",
    }
